import networkx as nx
import itertools

def is_girth_at_least_6(G):
    try:
        g = nx.girth(G)
        return g >= 6
    except:
        return False

def solve():
    # Try to build a graph with 11 vertices, girth 6, degrees 2-5
    # Start with a cycle of 11 vertices (girth 11)
    # Then add edges one by one, checking the girth

    import random

    for _ in range(10000):
        G = nx.cycle_graph(11)
        # Add some edges
        possible_edges = []
        for i in range(11):
            for j in range(i + 2, 11):
                if (i, j) not in G.edges() and (j, i) not in G.edges():
                    if not (i == 0 and j == 10): # Already in cycle
                        possible_edges.append((i, j))

        random.shuffle(possible_edges)

        for edge in possible_edges:
            G.add_edge(*edge)
            if not is_girth_at_least_6(G):
                G.remove_edge(*edge)
            else:
                # Check degrees
                degrees = [d for n, d in G.degree()]
                if all(2 <= d <= 5 for d in degrees):
                    # Check if we have at least one vertex with degree > 2
                    if any(d > 2 for d in degrees):
                        return list(G.edges())
    return None

print(solve())
